import sys
from collections import defaultdict

def find_parent(parent, x):
    if parent[x] == x:
        return x
    parent[x] = find_parent(parent, parent[x])
    return parent[x]

def union(parent, x, y):
    px = find_parent(parent, x)
    py = find_parent(parent, y)
    if px != py:
        if px < py:
            parent[px] = py
        else:
            parent[py] = px

def kruskal(parent, graph):
    mst_cost = 0
    operations = []
    for edge in graph:
        x, y, c = edge
        if find_parent(parent, x) != find_parent(parent, y):
            union(parent, x, y)
            operations.append((c, x, y))
    return operations

def calculate_max_energy(graph):
    operations = kruskal(parent, graph)
    max_energy = 0
    for cost, x, y in operations:
        if y != 2 and x != 2 and cost > max_energy:
            max_energy = cost
    return max_energy

