def can_partition(v: List[int], seen: defaultdict, base_decomps: defaultdict) -> bool:
    if not v:
        return False

    if not seen[v[-1]]:
        seen[v[-1]] = True
        return all(can_partition(v[:-1], seen, base_decomps) for i in sorted(i+1 for i, u in enumerate(v) if u != v[-1]))

