def count_ways(n: int, nums: List[int]) -> int:
    if not nums or any(num != -1 for num in nums):
        return 0
    ways = [1] * n

    last_level = -1
    for i, num in enumerate(nums):
        if num == -1:
            if last_level != -1:
                ways[last_level] = ways[last_level] * (last_level - 1) % MOD
            if last_level != -1:
                ways[i] = ways[i] * (i - last_level - 1) % MOD
        else:
            last_level = num

    other_nums = [num for num in range(1, n + 1) if num != last_level]
    if other_nums:
        for i in other_nums:
            ways[i] += sum(ways[j] for j in other_nums) % MOD

    return sum(ways) % MOD

