import sys

def mod_exp(base, exponent, mod):
    result = 1
    base = base % mod
    while exponent > 0:
        if exponent % 2 == 1:
            result = (result * base) % mod
        exponent = exponent >> 1
        base = (base * base) % mod
    return result

def chinese_remainder_theorem(a, b, m):
    res = 0
    prod = 1
    for i in range(len(m)):
        prod *= m[i]
        x = mod_exp(prod, prod, prod)
        while x < a[i]:
            x += prod
        res += x * b[i]
    return res % prod

def find_smallest_B(N, X, M):
    MOD = 998244353
    seen = [False] * MOD
    found = False
    res = 0

    # Compute the next possible B values
    while not found:
        for i in range(N):
            for j in range(N - i):
                if seen[(res + (2 ** j) * (2 ** i)) % MOD % MOD] == False:
                    seen[(res + (2 ** j) * (2 ** i)) % MOD % MOD] = True
                    res += (2 ** j) * (2 ** i)
                    continue
                else:
                    res += MOD * (2 ** j) * (2 ** i)
                    break
            else:
                res += MOD * (2 ** i)
                continue
        found = True
        if count(X):
            break

    return res % MOD if M != 0 else -1

def count(X):
    while X:
        if X % 2 == 0:
            X //= 2
        else:
            return False
    return True

