    adjacent_pairs = []
    for i in range(n):
        for j in range(i+1, n):
            if permutation[i] > permutation[j]:
                cost = abs(i - j)
                heapq.heappush(adjacent_pairs, (cost, i, j))
    min_cost = float('inf')
    operations = []
    while adjacent_pairs:
        cost, i, j = heappop(adjacent_pairs)
        if cost >= min_cost:
            continue
        min_cost = cost
        operations.append((i, j))
        if len(operations) == n-1:
            break
        if i == 0 or j == n-1:
            continue
        incoming_cost = abs(i-1) + abs(j+1)
        if j+1 < n and permutation[j+1] < permutation[j]:
            heapq.heappush(adjacent_pairs, (incoming_cost, i, j+1))
        if i-1 > 0 and permutation[i-1] < permutation[i]:
            heapq.heappush(adjacent_pairs, (incoming_cost, i-1, j))
    return min_cost, len(operations), operations

