def countWays(arr, levels):
    total_levels = len(arr)
    for i in range(total_levels):
        if arr[i] == -1:
            for level in range(1, total_levels + 1):
                if level != i:
                    solution = 1
                    for check_level in range(total_levels) - 1:
                        if arr[check_level] == level:
                            solution *= (levels - (check_level + 2))
                            solution %= 1000000007
                            levels -= (check_level + 2)
                    arr[i] = level
                    return solution
    return 1

