            network[value*i] = [(-float('inf'), -float('inf'), 1)]  # Increasing flow
            network[value*i+1] = [(-float('inf'), float('inf'), 1)]  # Increasing flow towards sink

    # Direct edges to source
    network[value*s].append((-float('inf'), -float('inf'), 0))

