from itertools import product

def longest_common_substring(start1, end1, start2, end2):
    if end1 < start2 or end2 < start1:
        return 0
    # Determine the alphabet size for common base
    alphabet_size = 36
    # Calculate the maximum possible length of the common substring
    max_length = min(end1 - start1 + 1, end2 - start2 + 1)
    if max_length > end1 - start1 or max_length > end2 - start2:
        return 0
    # Iterate over all possible substrings, using modulo to handle modulo 36
    for i in range(alphabet_size, len(alphabet_size ** max_length) - 1):
        for p in product(str(i), repeat=max_length):
            if int(p).__str__((alphabet_size ** max_length + int(p)) % alphabet_size + 1) == p:
                substr1 = ''.join(p[i % len(p)] for i in range(start1, end1+1))
                substr2 = ''.join(p[i % len(p)] for i in range(start2, end2+1))
                if substr1.startswith(substr2):
                    return len(substr2)
    return 0

