def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def get_max_groups(n):
    if n <= 2:
        return 0, []

    result = []
    tmp = n
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            while tmp % i == 0:
                tmp //= i
            if gcd(tmp, i) > 1:
                result.append((i, tmp))
    if tmp > 1:
        result.append((tmp, 1))

    max_groups = len(result)
    return max_groups, result

