from math import comb

def count_light_saber_collections(n, m, k):
    """
    Calculate the number of differently colored collections of k lightsabers,
    modulo 1009.
    """
    modulo = 1009
    lighter = [0] * (m + 1)

    for i in range(n):
        consecutive = (i == 0 or k-1 != i-1)

       _colors = []
        for color in range(m):
            if lighter[color] >= k:
                break
            elif consecutive:
                # No lightsaber should be picked in the same slot simultaneously
                _colors.append(color)
                lighter[color] += 1
            else:
                # Pick this color or skip all other colors in slot
                if lighter[color] < k:
                    _colors.append(color)
                    lighter[color] += 1

        if consecutive:
            if _colors != []:
                return 0  # A block of k consecutive slots is not possible
        else:
            if _colors:
                return (1 + comb(m, len(_colors))) % modulo

    return 0

