def pigeonhole_count(value, total):
    right_half, left_half = (p >> s).bit_count() for p, s in ((i, i >> leftmosts).bit_count() for i in range(1 << leftmosts) if i & value)
    return 3 * len(not right_half) if total > right_half + left_half + value else min(left_half + value, total)

